<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {Boxes,Search,Plus,LayoutGrid,List,Package,FolderKanban,ShoppingCart,ArrowDownToLine,ArrowUpFromLine,ArrowRightLeft,Database,History,ChevronRight,MapPin,X,Check,Download,Upload,Archive,Settings2,Printer,RefreshCw,CheckCircle2,AlertCircle,LoaderCircle,Layers,ExternalLink,ScanLine,LogOut} from '@lucide/vue';
import {api} from './api';
import AuthGate from './AuthGate.vue';
import AttachmentsPanel from './AttachmentsPanel.vue';
import ToolsPage from './ToolsPage.vue';
import PurchaseIntake from './PurchaseIntake.vue';
import PickingSheet from './PickingSheet.vue';
import {productName,cleanProductName,partLabel} from './productName';
const intake=ref<InstanceType<typeof PurchaseIntake>>();
import type {State,Part,Box,Stock,Slot,ProjectDetail,BomLine,Purchase,Parsed,PreviewRow,User} from './types';
const data=ref<State>({parts:[],boxes:[],projects:[],purchases:[],movements:[],storage:{database:'',backups:'',schema_version:1}});
const session=ref<User|null>(null),authLoading=ref(true),needsSetup=ref(false),tokenRequired=ref(false);
const canWrite=computed(()=>!!session.value&&session.value.role!=='viewer');
const isAdmin=computed(()=>session.value?.role==='admin');
const printReady=ref(false);
const page=ref('inventory'),loading=ref(true),busy=ref(false),error=ref(''),toast=ref('');
let toastTimer:ReturnType<typeof setTimeout>;
const notify=(message:string)=>{toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500);};
async function run(task:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await task();}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
async function refresh(){data.value=await api<State>('/state');if(selectedPartId.value&&!data.value.parts.some(p=>p.id===selectedPartId.value))selectedPartId.value='';if(selectedBoxId.value&&!data.value.boxes.some(b=>b.id===selectedBoxId.value))selectedBoxId.value='';if(project.value){if(data.value.projects.some(p=>p.id===project.value!.id))await loadProject(project.value.id);else project.value=null;}}
function sessionExpired(){session.value=null;modal.value='';pickingProjectId.value='';project.value=null;selectedPartId.value='';data.value={parts:[],boxes:[],projects:[],purchases:[],movements:[],storage:{database:'',backups:'',schema_version:2}};}
async function signedIn(user:User){session.value=user;needsSetup.value=false;loading.value=true;try{await refresh();const code=new URLSearchParams(window.location.search).get('scan');if(code)await resolveScan(code);}catch(e){error.value=String(e);}finally{loading.value=false;}}
async function logout(){await run(async()=>{await api('/auth/logout','POST');sessionExpired();});}
onMounted(async()=>{window.addEventListener('session-expired',sessionExpired);try{const result=await api<{user:User|null;setup_required:boolean;setup_token_required:boolean}>('/auth/status');needsSetup.value=result.setup_required;tokenRequired.value=result.setup_token_required;if(result.user)await signedIn(result.user);}catch(e){error.value=String(e);}finally{authLoading.value=false;loading.value=false;}});
onBeforeUnmount(()=>window.removeEventListener('session-expired',sessionExpired));
const nav=[{key:'inventory',label:'元件与位置',icon:Boxes},{key:'projects',label:'项目与 BOM',icon:FolderKanban},{key:'purchases',label:'采购与入库',icon:ShoppingCart},{key:'history',label:'库存流水',icon:History},{key:'settings',label:'数据与备份',icon:Database},{key:'tools',label:'扫码与协作',icon:ScanLine}];
const currentTitle=computed(()=>nav.find(n=>n.key===page.value)?.label||'工作台');
const query=ref(''),category=ref('全部类别'),showArchived=ref(false),view=ref('grid');
const selectedBoxId=ref(''),selectedPartId=ref(''),selectedSlotId=ref('');
const activeParts=computed(()=>data.value.parts.filter(p=>!p.archived));
const filteredParts=computed(()=>data.value.parts.filter(p=>Boolean(p.archived)===showArchived.value&&(category.value==='全部类别'||p.category===category.value)&&(!selectedBoxId.value||p.locations.some(s=>data.value.boxes.find(b=>b.id===selectedBoxId.value)?.slots.some(sl=>sl.id===s.slot_id)))&&matches(p)));
function matches(p:Part){return [p.name,p.value,p.package,p.category,p.supplier_code,p.notes,...Object.values(p.specs)].join(' ').toLocaleLowerCase().includes(query.value.toLocaleLowerCase());}
const categories=computed(()=>['全部类别',...new Set(data.value.parts.map(p=>p.category))]);
const selectedPart=computed(()=>data.value.parts.find(p=>p.id===selectedPartId.value));
const selectedBox=computed(()=>data.value.boxes.find(b=>b.id===selectedBoxId.value));
const visibleBoxes=computed(()=>data.value.boxes.filter(b=>!selectedBoxId.value||b.id===selectedBoxId.value));
const slots=computed(()=>data.value.boxes.flatMap(b=>b.slots.map(s=>({...s,label:`${b.code} / ${cell(s)}`}))));
const stockList=computed(()=>data.value.parts.flatMap(p=>p.locations));
const exactCount=computed(()=>activeParts.value.filter(p=>p.locations.some(s=>s.mode!=='exact')).length);
const openPurchases=computed(()=>data.value.purchases.filter(p=>!['received','cancelled'].includes(p.status)));
const modeName:Record<string,string>={exact:'精确',estimate:'估算',unknown:'未知'};
const projectStatus:Record<string,string>={draft:'备料中',reserved:'已占用',built:'已领料'};
const purchaseStatus:Record<string,string>={draft:'待购买',ordered:'待到货',partial:'部分到货',received:'已入库',cancelled:'已取消'};
const matchName:Record<string,string>={manual:'人工确认',supplier_code:'商城编号匹配',model:'完整型号匹配',exact:'参数匹配',value_package:'数值与封装匹配'};
const lineStatus:Record<string,string>={omit:'不贴装',external:'外部自备',enough:'数量足够',short:'缺料',count:'待盘点',review:'待确认',unmatched:'未匹配'};
function cell(s:{row_no:number;col_no:number}){return String.fromCharCode(65+s.row_no)+(s.col_no+1);}
function location(s:Stock){return `${s.box_code} / ${cell(s)}`;}
function specLabel(p:{specs:Record<string,string>}){return Object.entries(p.specs).map(([k,v])=>`${k} ${v}`).join(' · ');}
function stockAt(s:Slot){return stockList.value.find(st=>st.slot_id===s.id);}
function partAt(s:Slot){const st=stockAt(s);return data.value.parts.find(p=>p.id===st?.part_id);}
function slotVisible(s:Slot){const p=partAt(s);return !query.value&&category.value==='全部类别'?true:!!p&&matches(p)&&(category.value==='全部类别'||p.category===category.value);}
function selectSlot(s:Slot){selectedSlotId.value=s.id;const p=partAt(s);if(p){selectedPartId.value=p.id;}else{openStock(undefined,s.id);}}
function date(v:string){return new Date(v).toLocaleString('zh-CN',{hour12:false,month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
const modal=ref('');
let previousFocus:HTMLElement|null=null;
watch(modal,async(value,old)=>{if(value){if(!old)previousFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.modal input:not([type=checkbox]),.modal select,.modal button')?.focus();}else{previousFocus?.focus();}});
function trapFocus(e:KeyboardEvent){if(e.key!=='Tab')return;const els=Array.from(document.querySelectorAll<HTMLElement>('.modal button:not(:disabled),.modal input:not(:disabled):not([type=hidden]),.modal select:not(:disabled),.modal textarea:not(:disabled),.modal a[href]')).filter(el=>el.getClientRects().length>0);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}

const partForm=reactive({id:'',product_name:'',name:'',category:'电阻',package:'0603',value:'',supplier_code:'',notes:'',voltage:'',dielectric:'',tolerance:'',power:'',current:''});
const partFromLine=ref<BomLine|null>(null),partFromPurchase=ref(false);
function openPart(p?:Part,line?:BomLine){if(!canWrite.value){notify('当前账号为只读权限');return;}partFromLine.value=line||null;partFromPurchase.value=false;Object.assign(partForm,{id:p?.id||'',product_name:p?.product_name||'',name:p?.name||line?.name||'',category:p?.category||line?.category||'电阻',package:p?.package||line?.package||'0603',value:p?.value||line?.value||'',supplier_code:p?.supplier_code||'',notes:p?.notes||'',voltage:p?.specs['耐压']||line?.specs_data['耐压']||'',dielectric:p?.specs['介质']||line?.specs_data['介质']||'',tolerance:p?.specs['精度']||line?.specs_data['精度']||'',power:p?.specs['功率']||line?.specs_data['功率']||'',current:p?.specs['额定电流']||line?.specs_data['额定电流']||''});modal.value='part';}
async function savePart(){await run(async()=>{const specs:Record<string,string>={};for(const [key,value] of Object.entries({'耐压':partForm.voltage,'介质':partForm.dielectric,'精度':partForm.tolerance,'功率':partForm.power,'额定电流':partForm.current})){if(value.trim())specs[key]=value.trim();}const result=await api<{id:string}>(partForm.id?`/parts/${partForm.id}`:'/parts',partForm.id?'PUT':'POST',{...partForm,specs});selectedPartId.value=result.id;await refresh();modal.value='';notify(partFromLine.value?'档案已创建，请核对并关联到 BOM':'器件档案已保存');if(partFromLine.value){openMatch(partFromLine.value,result.id);}else if(partFromPurchase.value){purchaseForm.part_id=result.id;modal.value='purchase';partFromPurchase.value=false;notify('器件已建档，请继续填写采购计划');}});}
const boxForm=reactive({id:'',code:'',name:'',area:'',rows:3,cols:8});
function openBox(b?:Box){if(!canWrite.value){notify('当前账号为只读权限');return;}Object.assign(boxForm,{id:b?.id||'',code:b?.code||'',name:b?.name||'',area:b?.area||'',rows:b?.rows||3,cols:b?.cols||8});modal.value='box';}
async function saveBox(){await run(async()=>{const res=await api<{id:string}>(boxForm.id?`/boxes/${boxForm.id}`:'/boxes',boxForm.id?'PUT':'POST',boxForm);selectedBoxId.value=res.id;await refresh();modal.value='';notify('收纳盒已保存');});}
const stockForm=reactive({part_id:'',slot_id:'',quantity:0,mode:'exact',action:'count',note:''});
function openStock(p?:Part,slotId='',action='count'){if(!canWrite.value){notify('当前账号为只读权限');return;}const existing=p?.locations.find(s=>s.slot_id===slotId)||p?.locations[0];Object.assign(stockForm,{part_id:p?.id||'',slot_id:slotId||existing?.slot_id||'',quantity:action==='count'?(existing?.quantity??0):1,mode:existing?.mode||'exact',action,note:''});modal.value='stock';}
watch(()=>stockForm.slot_id,()=>{if(modal.value==='stock'&&stockForm.action==='count'){const s=stockList.value.find(s=>s.slot_id===stockForm.slot_id);stockForm.quantity=s?.quantity??0;stockForm.mode=s?.mode||'exact';}});
async function saveStock(){await run(async()=>{await api('/stock','POST',stockForm);selectedPartId.value=stockForm.part_id;await refresh();modal.value='';notify('库存已保存并写入流水');});}
const moveForm=reactive({stock_id:'',slot_id:''});
function openMove(s:Stock){if(!canWrite.value){notify('当前账号为只读权限');return;}moveForm.stock_id=s.id;moveForm.slot_id='';modal.value='move';}
const slotOptions=computed(()=>slots.value.filter(s=>{const p=modal.value==='receive'?receivePurchase.value?.part_id:modal.value==='move'?stockList.value.find(x=>x.id===moveForm.stock_id)?.part_id:stockForm.part_id;const st=stockAt(s);return !st||st.part_id===p;}));
async function saveMove(){await run(async()=>{await api('/stock/move','POST',moveForm);await refresh();modal.value='';notify('整格库存已移位');});}
async function clearStock(s:Stock){await run(async()=>{await api(`/stock/${s.id}/clear`,'POST');await refresh();notify('已释放空格，历史流水保留');});}
async function toggleArchive(p:Part){await run(async()=>{await api(`/parts/${p.id}/archive`,'POST',{archived:!p.archived});await refresh();notify(p.archived?'器件已恢复':'器件已归档');});}
const parsed=ref<Parsed|null>(null),importKind=ref('inventory'),preview=ref<{rows:PreviewRow[];errors:number}|null>(null);
const mapping=ref<Record<string,string>>({});
const importName=ref(''),importBoards=ref(1);
const fields=computed(()=>[['name','名称 / 型号'],['category','类别'],['package','封装'],['value','数值'],...(importKind.value==='inventory'?[['quantity','数量'],['box','盒号'],['cell','格号'],['mode','数量方式'],['supplier_code','商城编号'],['notes','备注']]:[['per_board','单板用量'],['designators','位号'],['supplier_code','商城编号']]),['耐压','耐压'],['介质','介质'],['精度','精度'],['功率','功率'],['额定电流','额定电流']]);
watch(mapping,()=>preview.value=null,{deep:true});
function importData(){return {rows:parsed.value?.rows||[],mapping:mapping.value,format:parsed.value?.format,sheet:parsed.value?.sheet,filename:parsed.value?.filename,name:importName.value,boards:importBoards.value,kind:importKind.value};}
async function parseFile(event:Event,kind:string){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await run(async()=>{const form=new FormData();form.append('file',file);form.append('kind',kind);parsed.value=await api<Parsed>('/files/parse','POST',form);mapping.value={...parsed.value.mapping};importKind.value=kind;importName.value=parsed.value.project_name||file.name.replace(/\.[^.]+$/,'');preview.value=null;modal.value='import';});input.value='';}
async function checkImport(){await run(async()=>{preview.value=await api('/import/preview','POST',importData());});}
async function commitImport(){await run(async()=>{if(importKind.value==='inventory'){const res=await api<{count:number}>('/import/commit','POST',importData());notify(`已导入 ${res.count} 行，导入前快照已保存`);await refresh();modal.value='';}else{const res=await api<{id:string}>('/projects','POST',importData());await refresh();modal.value='';page.value='projects';await loadProject(res.id);notify('BOM 已导入，核料完成');}});}
const project=ref<ProjectDetail|null>(null),pickingProjectId=ref('');
async function setSupply(line:BomLine,mode:string,note=''){await run(async()=>{await api(`/bom/${line.id}/supply`,'PUT',{mode,note});await loadProject(project.value!.id);});}
const projectPurchaseCount=computed(()=>data.value.purchases.filter(p=>p.project_id===project.value?.id).length);
async function loadProject(id:string){project.value=await api<ProjectDetail>(`/projects/${id}`);}
async function selectProject(id:string){await run(async()=>loadProject(id));}
async function rematchProject(){if(!project.value)return;await run(async()=>{await refresh();notify(`整张 BOM 已重新匹配：${project.value!.lines.length-project.value!.unresolved} 项已关联，${project.value!.unresolved} 项待处理`);});}
async function projectAction(action:string){if(!project.value)return;await run(async()=>{await api(`/projects/${project.value!.id}/${action}`,'POST');await refresh();notify(action==='reserve'?'库存已占用，其他项目无法重复分配':action==='release'?'已释放项目占用':'项目领料完成，库存与流水已更新');});}
async function deleteProject(){if(!project.value||!canWrite.value)return;const id=project.value.id;await run(async()=>{await api(`/projects/${id}`,'DELETE',{confirm:true});project.value=null;modal.value='';await refresh();if(data.value.projects[0])await loadProject(data.value.projects[0].id);notify('项目已删除，实物库存与历史流水已保留');});}
async function setBoards(event:Event){const boards=Number((event.target as HTMLInputElement).value);if(!project.value)return;await run(async()=>{await api(`/projects/${project.value!.id}`,'PUT',{boards});await refresh();});}
const matchLine=ref<BomLine|null>(null),matchForm=reactive({part_id:'',confirmed:false,reason:''});
function openMatch(line:BomLine,partId=''){if(!canWrite.value){notify('当前账号为只读权限');return;}matchLine.value=line;Object.assign(matchForm,{part_id:partId||line.part?.id||line.candidates[0]?.id||'',confirmed:false,reason:''});modal.value='match';}
const matchPart=computed(()=>data.value.parts.find(p=>p.id===matchForm.part_id));
async function saveMatch(){if(!matchLine.value)return;await run(async()=>{await api(`/bom/${matchLine.value!.id}/match`,'PUT',matchForm);await loadProject(project.value!.id);modal.value='';notify('已保存当前项目的人工匹配依据');});}
function createPurchasePart(){openPart();partFromPurchase.value=true;}
const purchaseForm=reactive({part_id:'',quantity:1,supplier:'',notes:'',project_id:''});
function openPurchase(partId='',quantity=1,projectId=''){if(!canWrite.value){notify('当前账号为只读权限');return;}Object.assign(purchaseForm,{part_id:partId,quantity,supplier:'',notes:'',project_id:projectId});modal.value='purchase';}
async function savePurchase(){await run(async()=>{await api('/purchases','POST',purchaseForm);await refresh();modal.value='';notify('已添加采购项，尚未增加库存');});}
async function purchaseAction(p:Purchase,action:string){await run(async()=>{await api(`/purchases/${p.id}/${action}`,'POST');await refresh();notify(action==='order'?'已标记购买，等待到货验收':'采购项已取消');});}
const purchaseFilter=ref('open');
const filteredPurchases=computed(()=>data.value.purchases.filter(p=>purchaseFilter.value==='all'||!['received','cancelled'].includes(p.status)));
const receivePurchase=ref<Purchase|null>(null),receiveForm=reactive({slot_id:'',quantity:1});
function openReceive(p:Purchase){if(!canWrite.value){notify('当前账号为只读权限');return;}receivePurchase.value=p;receiveForm.quantity=p.quantity-p.received;receiveForm.slot_id=data.value.parts.find(x=>x.id===p.part_id)?.locations.find(s=>s.mode==='exact')?.slot_id||'';modal.value='receive';}
async function receive(){await run(async()=>{await api(`/purchases/${receivePurchase.value!.id}/receive`,'POST',receiveForm);await refresh();modal.value='';notify('验收已入库，采购进度与库存已同步');});}
const restoreFile=ref<File|null>(null),restoreCounts=ref<Record<string,number>|null>(null),restoreConfirmed=ref(false);
async function previewRestore(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await run(async()=>{const form=new FormData();form.append('file',file);const result=await api<{counts:Record<string,number>}>('/restore/preview','POST',form);restoreFile.value=file;restoreCounts.value=result.counts;restoreConfirmed.value=false;modal.value='restore';});input.value='';}
async function restore(){await run(async()=>{const form=new FormData();form.append('file',restoreFile.value!);const res=await fetch('/api/restore',{method:'POST',headers:{'X-Confirm-Restore':'RESTORE'},body:form});const result=await res.json();if(!res.ok)throw new Error(result.detail);project.value=null;selectedPartId.value='';selectedBoxId.value='';await refresh();modal.value='';notify('恢复完成；恢复前的数据已自动备份');});}
async function demo(){await run(async()=>{await api('/demo','POST');await refresh();notify('示例已载入，可从元件盒开始体验');});}
async function printLabels(){printReady.value=true;await nextTick();await Promise.all(Array.from(document.querySelectorAll<HTMLImageElement>('.print-area img')).map(image=>image.complete?Promise.resolve():new Promise<void>(resolve=>{image.onload=()=>resolve();image.onerror=()=>resolve();setTimeout(resolve,8000);})));window.print();}
async function resolveScan(code:string){await run(async()=>{const result=await api<{part_id?:string;slot_id?:string;box_id?:string;query?:string}>('/scan/resolve','POST',{code});query.value=result.query||'';category.value='全部类别';showArchived.value=false;selectedBoxId.value=result.box_id||'';selectedSlotId.value=result.slot_id||'';selectedPartId.value=result.part_id||'';page.value='inventory';view.value=result.query?'list':'grid';notify(result.query?'已按编码搜索，请核对结果':'已定位标签对应位置');});}
async function importOcr(csv:string,kind:string){await run(async()=>{const form=new FormData();form.append('file',new File([csv],'OCR-校对.csv',{type:'text/csv'}));form.append('kind',kind);parsed.value=await api<Parsed>('/files/parse','POST',form);mapping.value={...parsed.value.mapping};importKind.value=kind;importName.value='OCR 清单';preview.value=null;modal.value='import';});}
const historyQuery=ref('');
const filteredHistory=computed(()=>data.value.movements.filter(m=>[m.part_name,m.kind,m.note,m.box_code].join(' ').toLowerCase().includes(historyQuery.value.toLowerCase())));
watch(page,()=>{error.value='';});
</script>

<template>
 <div v-if="authLoading" class="loading">正在打开工作台…</div>
 <AuthGate v-else-if="!session" :setup="needsSetup" :token-required="tokenRequired" @ready="signedIn"/>
 <div v-else class="app-shell" :class="{'read-only':!canWrite}">
  <aside class="sidebar">
   <a class="brand" href="#" @click.prevent="page='inventory'"><span class="brand-mark"><Layers :size="23"/></span><span>料格<small>PARTS WORKBENCH</small></span></a>
   <div class="workspace-label">个人硬件工作室 <span>本地</span></div>
   <nav aria-label="主要页面"><button v-for="n in nav" :key="n.key" :class="{active:page===n.key}" @click="page=n.key"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><span v-if="n.key==='purchases'&&openPurchases.length" class="nav-count">{{openPurchases.length}}</span></button></nav>
   <div class="sidebar-bottom"><div class="account-row"><span>{{session.display_name}}</span><button aria-label="退出登录" @click="logout"><LogOut :size="15"/></button></div><span class="online-dot"></span>SQLite 本地存储<small>每一颗元件，都有位置。</small></div>
  </aside>
  <main class="main-shell">
   <header class="topbar"><div><span class="breadcrumb">工作台</span><ChevronRight :size="14"/><strong>{{currentTitle}}</strong></div><span class="top-caption">专注创造 · 有序收纳</span><button class="icon-button logout-mobile" aria-label="退出当前账号" @click="logout"><LogOut :size="16"/></button><button class="icon-button" aria-label="刷新数据" :disabled="busy" @click="run(refresh)"><RefreshCw :size="16"/></button></header>
   <div class="page-content">
    <div v-if="error" class="error-banner" role="alert"><AlertCircle :size="18"/><span>{{error}}</span><button class="icon-button" aria-label="关闭错误" @click="error=''"><X :size="16"/></button></div>
    <div v-if="loading" class="loading"><LoaderCircle class="spin"/>正在打开工作台…</div>
    <template v-else-if="page==='inventory'">
     <div class="page-heading"><div><div class="eyebrow">INVENTORY / STORAGE</div><h1>让每一颗元件，<br class="mobile-only">都有迹可循。</h1><p>从器件到格子，把找料的时间还给创造。</p></div><div class="heading-actions" v-if="canWrite"><label class="button secondary"><Upload :size="16"/>批量导入<input type="file" accept=".csv,.tsv,.xls,.xlsx" hidden @change="parseFile($event,'inventory')"></label><button class="primary" @click="openPart()"><Plus :size="17"/>新建元件</button></div></div>
     <div class="inventory-summary"><span><strong>{{activeParts.length}}</strong> 种元件</span><i></i><span><strong>{{data.boxes.length}}</strong> 个收纳盒</span><i></i><span :class="{'warm-text':exactCount>0}"><strong>{{exactCount}}</strong> 种含估算 / 未知数量</span><a class="text-button" href="/api/export/inventory"><Download :size="14"/>导出清单</a></div>
     <div class="inventory-layout">
      <section class="inventory-main">
       <div class="filterbar"><div class="search-field"><Search :size="17"/><input v-model="query" aria-label="搜索元件" placeholder="搜索型号、数值、封装或备注…"><button v-if="query" class="icon-button" aria-label="清除搜索" @click="query=''"><X :size="14"/></button></div><select v-model="category" aria-label="筛选类别"><option v-for="c in categories" :key="c">{{c}}</option></select><div class="view-toggle"><button :class="{active:view==='grid'}" aria-label="格子视图" @click="view='grid'"><LayoutGrid :size="17"/></button><button :class="{active:view==='list'}" aria-label="列表视图" @click="view='list'"><List :size="17"/></button></div></div>
       <div class="box-tabs"><button :class="{selected:!selectedBoxId}" @click="selectedBoxId=''">全部收纳盒</button><button v-for="b in data.boxes" :key="b.id" :class="{selected:selectedBoxId===b.id}" @click="selectedBoxId=b.id"><span class="mono">{{b.code}}</span> {{b.name}}</button><button v-if="canWrite" class="add-box" @click="openBox()"><Plus :size="14"/>新建盒子</button></div>
       <label class="archive-toggle"><input v-model="showArchived" type="checkbox" @change="view='list'">查看已归档元件</label>
       <template v-if="view==='grid'&&!showArchived">
        <section v-for="b in visibleBoxes" :key="b.id" class="box-panel">
         <div class="box-heading"><div><span class="box-code mono">{{b.code}}</span><h2>{{b.name}}</h2><span class="subtle">{{b.rows}} × {{b.cols}} 格</span></div><div><span class="box-area"><MapPin :size="13"/>{{b.area||'未设置区域'}}</span><button class="icon-button" :aria-label="'编辑 '+b.code" @click="openBox(b)"><Settings2 :size="15"/></button></div></div>
         <div class="cell-grid" :style="{'--cols':b.cols}"><button v-for="s in b.slots" :key="s.id" class="slot" :class="{filled:partAt(s),selected:selectedSlotId===s.id,dimmed:!slotVisible(s)}" @click="selectSlot(s)"><span class="slot-top"><span class="mono">{{cell(s)}}</span><span>{{partAt(s)?.package}}</span></span><strong :title="partAt(s)?.name">{{productName(partAt(s))}}</strong><span v-if="stockAt(s)" class="slot-quantity"><span :class="{'estimate-dot':stockAt(s)?.mode!=='exact'}"></span>{{stockAt(s)?.quantity??'—'}} <small>{{modeName[stockAt(s)!.mode]}}</small></span><span v-else class="slot-empty">＋ 放入元件</span></button></div>
        </section>
        <div v-if="!data.boxes.length" class="empty-state"><Boxes :size="40"/><h2>先给元件安排一个家</h2><p>新建收纳盒，设置行列，再把器件放进对应格子。</p><button class="primary" @click="openBox()"><Plus :size="16"/>创建第一个盒子</button><button v-if="!data.parts.length" class="text-button" :disabled="busy" @click="demo">或载入可编辑的示例数据</button></div>
       </template>
       <div v-else class="table-wrap"><table><thead><tr><th>元件</th><th>封装 / 类别</th><th>位置</th><th>可用 / 占用</th><th></th></tr></thead><tbody><tr v-for="p in filteredParts" :key="p.id" :class="{highlight:selectedPartId===p.id}" @click="selectedPartId=p.id"><td><strong>{{p.name}}</strong><small>{{p.value}} {{specLabel(p)}}</small></td><td>{{p.package||'—'}}<small>{{p.category}}</small></td><td>{{p.locations.map(location).join('、')||'未放置'}}</td><td class="mono">{{p.available}} / {{p.reserved}}</td><td><button class="icon-button" :aria-label="'编辑 '+p.name" @click.stop="openPart(p)"><Settings2 :size="15"/></button></td></tr><tr v-if="!filteredParts.length"><td colspan="5" class="empty-table">没有符合条件的元件</td></tr></tbody></table></div>
       <div class="inventory-bottom"><span>固定位置编码 · 支持一物多处</span><button class="text-button" @click="printLabels"><Printer :size="14"/>打印当前盒子标签</button></div>
      </section>
      <aside class="detail-panel" v-if="selectedPart">
       <div class="detail-top"><span class="eyebrow">COMPONENT DETAILS</span><button class="icon-button" aria-label="关闭元件详情" @click="selectedPartId='';selectedSlotId=''"><X :size="16"/></button></div><div class="component-icon"><Package :size="25"/></div><h2>{{selectedPart.name}}</h2><p class="subtle">{{selectedPart.category}} <span v-if="selectedPart.package"> / {{selectedPart.package}}</span></p>
       <dl class="specs"><template v-if="selectedPart.value"><dt>数值</dt><dd>{{selectedPart.value}}</dd></template><template v-for="(v,k) in selectedPart.specs" :key="k"><dt>{{k}}</dt><dd>{{v}}</dd></template><dt>商城编号</dt><dd>{{selectedPart.supplier_code||'—'}}</dd></dl>
       <div class="stock-numbers"><div><strong>{{selectedPart.available}}</strong><span>精确可用</span></div><div><strong>{{selectedPart.reserved}}</strong><span>项目占用</span></div></div>
       <div class="section-label">存放位置 <span>{{selectedPart.locations.length}} 处</span></div><div v-for="s in selectedPart.locations" :key="s.id" class="location-card"><div><span class="location-code mono">{{location(s)}}</span><span>{{s.quantity??'—'}} · {{modeName[s.mode]}}</span></div><div v-if="canWrite" class="location-actions"><button @click="openStock(selectedPart,s.slot_id,'in')">入库</button><button @click="openStock(selectedPart,s.slot_id,'out')">领料</button><button @click="openStock(selectedPart,s.slot_id)">盘点</button><button @click="openMove(s)">移位</button><button v-if="s.quantity===0" @click="clearStock(s)" :disabled="busy">清空格子</button></div></div>
       <button class="outline full" v-if="canWrite&&!selectedPart.archived" @click="openStock(selectedPart)"><Plus :size="15"/>添加存放位置</button><div v-if="selectedPart.locations.some(s=>s.mode!=='exact')" class="callout warm">估算与未知数量不参与自动占用，请盘点后用于项目领料。</div><p v-if="selectedPart.notes" class="notes">{{selectedPart.notes}}</p><div v-if="canWrite" class="detail-actions"><button class="secondary" @click="openPart(selectedPart)"><Settings2 :size="15"/>编辑档案</button><button class="icon-button" :aria-label="selectedPart.archived?'恢复元件':'归档元件'" :disabled="busy" @click="toggleArchive(selectedPart)"><Archive :size="16"/></button></div>
       <div class="part-code"><img :src="'/api/qr/part/'+selectedPart.id" :alt="selectedPart.name+' 二维码'"><span>器件定位标签<small>在「扫码与协作」扫描可打开此档案</small></span></div>
       <AttachmentsPanel :part-id="selectedPart.id" :writable="canWrite"/>
      </aside>
      <aside v-else class="detail-placeholder"><Package :size="30"/><h3>从一个格子开始</h3><p>选择元件，查看参数、库存和存放位置。</p><span>整齐一点，灵感多一点。</span></aside>
     </div>
    </template>

    <template v-else-if="page==='projects'">
     <div class="page-heading"><div><div class="eyebrow">PROJECTS / BILL OF MATERIALS</div><h1>先备齐，再动手。</h1><p>把物料清单变成可执行的备料计划。</p></div><div class="heading-actions"><a class="button secondary" href="/api/export/bom-template"><Download :size="16"/>BOM 模板</a><label class="button primary"><Plus :size="17"/>导入 BOM<input type="file" accept=".csv,.tsv,.xls,.xlsx" hidden @change="parseFile($event,'bom')"></label></div></div>
     <div class="project-picker"><button v-for="p in data.projects" :key="p.id" :class="{selected:project?.id===p.id}" @click="selectProject(p.id)"><FolderKanban :size="17"/><strong>{{p.name}}</strong><span class="badge neutral">{{projectStatus[p.status]}}</span></button></div>
     <section v-if="project" class="panel">
      <div class="project-header"><div><h2>{{project.name}}</h2><span class="subtle">{{project.lines.length}} 项物料 · {{projectStatus[project.status]}}</span></div><div class="row"><button class="primary" :disabled="busy" @click="pickingProjectId=project.id"><MapPin :size="15"/>位置清单</button><a class="button secondary" :href="`/api/projects/${project.id}/picking/map`" target="_blank" rel="noopener"><LayoutGrid :size="15"/>打印位置图</a><button v-if="project.status==='draft'" class="secondary" :disabled="busy" @click="rematchProject"><RefreshCw :size="15"/>重新自动匹配</button><label class="inline-label">制作 <input type="number" :value="project.boards" min="1" max="100000" :disabled="busy||!canWrite||project.status!=='draft'" @change="setBoards"> 块</label><button v-if="canWrite" class="secondary red-text" :disabled="busy" @click="modal='project-delete'">删除项目</button></div></div>
      <div class="bom-summary"><span v-if="project.omitted">{{project.omitted}} 项不贴装</span><span v-if="project.external">{{project.external}} 项外部自备</span><span><CheckCircle2 :size="16"/>{{project.lines.filter(l=>l.status==='enough').length}} 项够用</span><span class="warm-text"><AlertCircle :size="16"/>{{project.unresolved}} 项待匹配</span><span class="red-text">{{project.shortages.length}} 种缺料</span><span v-if="project.uncertain" class="warm-text">{{project.uncertain}} 项需盘点</span></div>
      <div v-if="project.status==='built'" class="callout">该项目已完成一次性领料。下表按当前剩余库存重新核对；历史领料请在库存流水查看。</div>
      <div v-if="project.source?.format==='easyeda_bom'" class="callout">已识别立创 / 嘉立创 EDA BOM · {{project.source.filename}} · {{project.source.sheet}}。商城编号唯一命中即自动关联；资料差异保留提示，无编号时再按完整型号或阻容感规格匹配。</div><div class="table-wrap"><table class="bom-table"><thead><tr><th>需求器件</th><th>匹配与依据</th><th>需求 / 可用</th><th>核料结果</th><th></th></tr></thead><tbody><tr v-for="l in project.lines" :key="l.id"><td><strong>{{l.name}}</strong><small v-if="l.value&&l.value!==l.name">数值 {{l.value}}</small><small v-if="l.supplier_code">商城编号 {{l.supplier_code}}</small><small>{{l.package||'封装未提供'}} · {{l.category||'类别未提供'}}</small><small>{{Object.entries(l.specs_data).map(([k,v])=>k+' '+v).join(' · ')}}</small><small>{{l.designators||'无位号'}} · 单板 {{l.per_board}}</small><small v-for="warning in l.warnings" :key="warning" class="warm-text">{{warning}}</small></td><td><strong>{{l.supply_mode==='omit'?'不贴装，不取料':l.supply_mode==='external'?'外部自备 / 样品':l.part?partLabel(l.part):'未关联器件'}}</strong><small v-if="l.part">{{l.part.package}} · {{matchName[l.match]||'参数匹配'}}<template v-if="l.match==='supplier_code'&&l.part.supplier_code"> · {{l.part.supplier_code}}</template></small><small v-if="l.part">{{l.part.locations.map(location).join('、')||'无存放位置'}}</small><small v-else-if="l.supply_mode==='stock'">{{l.candidates.length?l.candidates.length+' 个相似候选，请核对':'请先建档或选择已有器件'}}</small><small v-if="l.part&&l.missing_specs?.length&&!['supplier_code','model'].includes(l.match)" class="warm-text">BOM 未指定{{l.missing_specs.join('、')}}，请按用途核对</small><small v-for="note in l.match_notes" :key="note" class="warm-text">{{note}}</small><small v-if="l.unmatched_reason" class="warm-text">{{l.unmatched_reason}}</small><small v-if="l.reason">{{l.reason}}</small></td><td class="mono"><template v-if="l.supply_mode==='omit'">不取料</template><template v-else-if="l.supply_mode==='external'">自备 {{l.demand}}</template><template v-else>{{l.demand}} / {{l.part?l.available_before:'—'}}<small v-if="l.shortage">缺 {{l.shortage}}</small></template></td><td><span class="badge" :class="l.status==='enough'?'good':l.status==='short'?'bad':'warm'">{{lineStatus[l.status]}}</span></td><td><select class="supply-select" :aria-label="l.line_no+' '+l.name+' 备料方式'" :value="l.supply_mode" :disabled="busy||!canWrite||project.status!=='draft'" @change="setSupply(l,($event.target as HTMLSelectElement).value)"><option value="stock">库存取料</option><option value="omit">不贴装</option><option value="external">外部自备 / 样品</option></select><input v-if="l.supply_mode==='external'" :aria-label="l.line_no+' '+l.name+' 自备说明'" v-model="l.supply_note" placeholder="样品来源 / 存放位置（选填）" :disabled="busy||!canWrite||project.status!=='draft'" maxlength="500" @change="setSupply(l,'external',($event.target as HTMLInputElement).value)"><button v-if="l.supply_mode==='stock'" class="text-button" :disabled="project.status!=='draft'" @click="openMatch(l)">核对关联</button><button v-if="!l.part&&l.supply_mode==='stock'" class="text-button" :disabled="project.status!=='draft'" @click="openPart(undefined,l)">补建档</button></td></tr></tbody></table></div>
      <div class="project-footer"><p>可先输出已知位置。不贴装和外部自备不占用库存；只对库存取料项核对数量。</p><div class="row"><button class="primary" :disabled="busy" @click="pickingProjectId=project.id"><MapPin :size="16"/>下一步：位置清单</button><button v-if="project.status==='draft'&&project.stock_lines>0" class="secondary" :disabled="busy||!project.ready" @click="projectAction('reserve')"><Check :size="16"/>占用库存取料项</button><template v-if="project.status==='reserved'"><button class="secondary" :disabled="busy" @click="projectAction('release')">释放占用</button><button class="primary" :disabled="busy" @click="modal='issue'"><ArrowUpFromLine :size="16"/>确认整单领料</button></template></div></div>
      <div v-if="project.shortages.length&&project.status==='draft'" class="shortage-section"><h3>采购建议</h3><p class="subtle">按已确认器件汇总。请先处理“待盘点”，并查看已有在途采购，避免重复购买。</p><div v-for="s in project.shortages" :key="s.part.id" class="shortage-row"><strong>{{s.part.name}} <small>{{s.part.package}}</small></strong><span>缺 {{s.quantity}} 颗</span><button class="secondary" @click="openPurchase(s.part.id,s.quantity,project.id)"><Plus :size="14"/>添加采购</button></div></div>
     </section>
     <div v-else class="empty-state"><FolderKanban :size="40"/><h2>{{data.projects.length?'选择一个项目，开始核料':'从一份 BOM 开始'}}</h2><p>支持 CSV、TSV、XLS、XLSX，可直接导入立创 / 嘉立创 EDA BOM，自动识别表头和常用列。</p><p class="subtle">优先按商城编号自动关联，资料差异单独提示；多个命中或找不到库存时显示具体原因。</p></div>
    </template>

    <template v-else-if="page==='purchases'">
     <div class="page-heading"><div><div class="eyebrow">PURCHASES / RECEIVING</div><h1>补齐缺料，安心开工。</h1><p>从采购清单到实物入格，每一步都清楚。</p></div><button v-if="canWrite" class="primary" @click="openPurchase()"><Plus :size="16"/>新建采购计划</button></div>
     <PurchaseIntake ref="intake" :state="data" :writable="canWrite" @changed="run(refresh)"/>
     <div class="toolbar"><div class="segmented"><button :class="{active:purchaseFilter==='open'}" @click="purchaseFilter='open'">进行中 {{openPurchases.length}}</button><button :class="{active:purchaseFilter==='all'}" @click="purchaseFilter='all'">全部采购</button></div><span class="subtle">已购买的物料在验收前不会计入库存。</span></div>
     <section class="panel"><div class="table-wrap"><table><thead><tr><th class="row-number">序号</th><th>采购器件</th><th>项目 / 供应商</th><th>已入库 / 采购</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="(p,index) in filteredPurchases" :key="p.id"><td class="mono row-number">{{index+1}}</td><td><strong>{{cleanProductName(p.product_name||p.part_name)}}</strong><small :title="p.part_name">型号 {{p.part_name}}</small><small>{{p.package}} · {{Object.values(JSON.parse(p.specs)).join(' / ')}}</small><small v-if="p.order_id" class="mono">{{p.order_id}}</small><small>{{p.notes}}</small></td><td>{{p.project_name||'日常补货'}}<small>{{p.supplier||'未指定供应商'}}</small></td><td class="mono">{{p.received}} / {{p.quantity}}</td><td><span class="badge" :class="p.status==='received'?'good':p.status==='cancelled'?'neutral':'warm'">{{purchaseStatus[p.status]}}</span></td><td><div v-if="canWrite" class="row"><button v-if="['partial','received'].includes(p.status)" class="secondary" :disabled="busy" @click="intake?.openCorrection([p.id])">修改验收</button><button v-if="p.status==='draft'" class="secondary" :disabled="busy" @click="purchaseAction(p,'order')">标记已购买</button><button v-if="['ordered','partial'].includes(p.status)" class="primary small" @click="openReceive(p)"><ArrowDownToLine :size="14"/>验收入库</button><button v-if="['draft','ordered'].includes(p.status)" class="text-button" :disabled="busy" @click="purchaseAction(p,'cancel')">取消</button></div></td></tr><tr v-if="!filteredPurchases.length"><td colspan="6"><div class="empty-state compact"><ShoppingCart :size="32"/><h3>采购清单很清爽</h3><p>从项目缺料添加采购，或手动创建日常补货。</p></div></td></tr></tbody></table></div></section>
    </template>

    <template v-else-if="page==='history'">
     <div class="page-heading"><div><div class="eyebrow">INVENTORY / ACTIVITY</div><h1>每一次变动，都有记录。</h1><p>最近 300 条入库、领料、盘点与移位记录。</p></div></div><div class="toolbar"><div class="search-field"><Search :size="17"/><input v-model="historyQuery" aria-label="搜索流水" placeholder="搜索器件、盒号或备注…"></div></div><section class="panel table-wrap"><table><thead><tr><th>时间</th><th>器件 / 位置</th><th>操作</th><th>之前 → 之后</th><th>备注</th></tr></thead><tbody><tr v-for="m in filteredHistory" :key="m.id"><td class="mono">{{date(m.created_at)}}</td><td><strong>{{m.part_name}}</strong><small>{{m.box_code}} / {{cell(m)}}</small></td><td><span class="badge neutral">{{m.kind}}</span></td><td class="mono">{{m.before_qty??'未知'}} → {{m.after_qty??'未知'}}</td><td>{{m.note||'—'}}</td></tr><tr v-if="!filteredHistory.length"><td colspan="5" class="empty-table">还没有符合条件的库存流水</td></tr></tbody></table></section>
    </template>

    <ToolsPage v-else-if="page==='tools'" :user="session" @resolve="resolveScan" @import-csv="importOcr"/>
    <template v-else-if="page==='settings'">
     <div class="page-heading"><div><div class="eyebrow">DATA / BACKUP</div><h1>数据留在手里，心里有底。</h1><p>库存保存在本地 SQLite 数据库，备份后可以换机恢复。</p></div></div>
     <div class="settings-grid"><section class="panel settings-card" v-if="isAdmin"><div class="settings-icon"><Database :size="24"/></div><h2>数据库备份</h2><p>生成一致的 SQLite 快照，包含器件、位置、项目、采购和全部流水。</p><a class="button primary" href="/api/backup"><Download :size="16"/>下载完整备份</a><div class="callout">包含照片与资料附件。每次启动、导入、升级和恢复前会保存本地快照。</div></section><section class="panel settings-card" v-if="isAdmin"><div class="settings-icon"><RefreshCw :size="24"/></div><h2>从备份恢复</h2><p>支持 v1 / v2 备份，恢复物料、项目、附件。当前成员与登录状态保留，原数据另存快照。</p><label class="button secondary"><Upload :size="16"/>选择 SQLite 备份<input type="file" accept=".sqlite3,.sqlite,.db" hidden @change="previewRestore"></label></section><section class="panel settings-card"><h2>清单与模板</h2><p>批量入库需先创建对应盒子。CSV 支持 UTF-8 和 GB18030；普通物料读取第一个工作表，立创 BOM 自动定位明细表。</p><div class="stack-links"><a href="/api/export/inventory"><Download :size="15"/>导出当前库存 CSV</a><a href="/api/export/template"><Download :size="15"/>下载物料导入模板</a><a href="/api/export/bom-template"><Download :size="15"/>下载 BOM 模板</a></div></section><section class="panel settings-card"><h2>存储位置</h2><dl class="path-list"><dt>数据库</dt><dd>{{data.storage.database}}</dd><dt>本地快照目录</dt><dd>{{data.storage.backups}}</dd></dl><p class="subtle">默认仅本机访问。手机与 NAS 部署说明见项目 README。</p><button v-if="canWrite&&!data.parts.length&&!data.boxes.length" class="secondary" :disabled="busy" @click="demo">载入示例数据</button></section></div>
    </template>
   </div>
  </main>
  <div v-if="toast" class="toast" role="status"><CheckCircle2 :size="18"/>{{toast}}</div>
  <div v-if="busy" class="busy-indicator" role="status"><LoaderCircle :size="15" class="spin"/>正在处理</div>

  <PickingSheet v-if="pickingProjectId" :project-id="pickingProjectId" @close="pickingProjectId=''"/>
  <div v-if="modal" class="modal-backdrop" @click.self="!busy&&(modal='')"><section class="modal" :class="{wide:modal==='import'}" role="dialog" aria-modal="true" :aria-label="{part:'器件档案',box:'收纳盒',stock:'库存操作',move:'整格移位',import:'导入预览',match:'核对器件',purchase:'采购',receive:'验收入库',restore:'恢复备份',issue:'项目领料','project-delete':'删除项目'}[modal]" @keydown="trapFocus" @keydown.esc="!busy&&(modal='')">
   <div class="modal-header"><h2>{{{part:partForm.id?'编辑器件档案':'新建器件档案',box:boxForm.id?'编辑收纳盒':'新建收纳盒',stock:stockForm.action==='count'?'设置 / 盘点库存':stockForm.action==='in'?'物料入库':'物料领料',move:'整格移位',import:importKind==='inventory'?'批量导入元件':'导入项目 BOM',match:'核对器件与匹配',purchase:'添加采购项',receive:'到货验收与入库',restore:'确认恢复备份',issue:'确认项目领料','project-delete':'删除项目'}[modal]}}</h2><button class="icon-button" :disabled="busy" aria-label="关闭弹窗" @click="modal=''"><X :size="20"/></button></div>
   <div v-if="error" class="error-banner" role="alert">{{error}}</div>
   <form v-if="modal==='part'" @submit.prevent="savePart"><div class="form-grid"><label class="span2">商品名称<input v-model="partForm.product_name" maxlength="2000" placeholder="选填，留空时沿用原始描述或型号"></label><label class="span2">名称 / 完整型号<input v-model="partForm.name" required maxlength="200" placeholder="例如 10 kΩ / STM32F103C8T6"></label><label>类别<input v-model="partForm.category" list="part-categories" required><datalist id="part-categories"><option v-for="c in ['电阻','电容','电感','二极管','三极管','MOS管','芯片','MCU','连接器','模块','其他']" :key="c">{{c}}</option></datalist></label><label>封装<input v-model="partForm.package" placeholder="0603 / SOT-23 / LQFP-48"></label><label>数值<input v-model="partForm.value" placeholder="10k / 100nF / 10uH"></label><label>商城编号<input v-model="partForm.supplier_code" placeholder="选填"></label><label>耐压<input v-model="partForm.voltage" placeholder="例如 25V"></label><label>介质<input v-model="partForm.dielectric" placeholder="例如 X7R"></label><label>精度<input v-model="partForm.tolerance" placeholder="例如 1%"></label><label>功率<input v-model="partForm.power" placeholder="例如 0.1W"></label><label>额定电流<input v-model="partForm.current" placeholder="例如 1A"></label><label class="span2">备注<textarea v-model="partForm.notes" rows="2" placeholder="用途、来源、注意事项…"></textarea></label></div><p class="form-hint">建档后在元件详情中添加存放位置和数量。编辑档案会重新核对未占用项目的匹配。</p><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">保存档案</button></div></form>
   <form v-else-if="modal==='box'" @submit.prevent="saveBox"><div class="form-grid"><label>盒号<input v-model="boxForm.code" required placeholder="R01" pattern="[A-Za-z0-9_-]+"></label><label>名称<input v-model="boxForm.name" required placeholder="贴片电阻"></label><label class="span2">所在区域<input v-model="boxForm.area" placeholder="工作台左侧 / 柜子第二层"></label><label>行数<input v-model.number="boxForm.rows" type="number" min="1" max="20" :disabled="!!boxForm.id" required></label><label>列数<input v-model.number="boxForm.cols" type="number" min="1" max="20" :disabled="!!boxForm.id" required></label></div><p class="form-hint">创建后固定格子编码。需要改变布局时新建盒子并移位。</p><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">保存盒子</button></div></form>
   <form v-else-if="modal==='stock'" @submit.prevent="saveStock"><div class="form-grid"><label class="span2">器件<select v-model="stockForm.part_id" required><option value="" disabled>请选择器件</option><option v-for="p in activeParts" :value="p.id" :key="p.id">{{p.name}} · {{p.package}} · {{specLabel(p)}}</option></select></label><label class="span2">存放位置<select v-model="stockForm.slot_id" required><option value="" disabled>请选择格子</option><option v-for="s in slotOptions" :key="s.id" :value="s.id">{{s.label}}</option></select></label><label v-if="stockForm.action==='count'">数量方式<select v-model="stockForm.mode"><option value="exact">精确</option><option value="estimate">估算</option><option value="unknown">未知</option></select></label><label>{{stockForm.action==='count'?'盘点后数量':'本次数量'}}<input v-model.number="stockForm.quantity" type="number" :min="stockForm.action==='count'?0:1" step="1" :disabled="stockForm.action==='count'&&stockForm.mode==='unknown'" required></label><label class="span2">操作备注<input v-model="stockForm.note" placeholder="采购、项目或盘点说明"></label></div><p class="form-hint">入库与领料保留原数量方式；估算或未知库存须通过盘点转为精确。</p><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">确认并记录流水</button></div></form>
   <form v-else-if="modal==='move'" @submit.prevent="saveMove"><p class="form-hint">将该格全部物料移到另一格。两格合并需使用相同的数量记录方式。</p><label>目标位置<select v-model="moveForm.slot_id" required><option value="" disabled>请选择目标格子</option><option v-for="s in slotOptions" :key="s.id" :value="s.id">{{s.label}}</option></select></label><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">确认整格移位</button></div></form>
   <form v-else-if="modal==='import'&&parsed" @submit.prevent="commitImport"><p class="form-hint">{{parsed.filename}} · 共 {{parsed.rows.length}} 行。先确认列对应关系，预览无误后提交。</p><div v-if="parsed.format==='easyeda_bom'" class="callout">已识别立创 / 嘉立创 EDA BOM：{{parsed.sheet}}，表头在第 {{parsed.header_row}} 行。数量按单板用量导入；C0603 / R0603 等封装已规范。已忽略 Manufacturer Part 和 Manufacturer 两列，请核对商城编号、数值和封装。</div><div v-if="importKind==='bom'" class="form-grid"><label>项目名称<input v-model="importName" required></label><label>制作板数<input v-model.number="importBoards" type="number" min="1" required></label></div><div class="mapping-grid"><label v-for="[key,label] in fields" :key="key">{{label}}<select v-model="mapping[key]"><option value="">不导入</option><option v-for="h in parsed.headers" :key="h" :value="h">{{h}}</option></select></label></div><div class="row"><button type="button" class="secondary" :disabled="busy" @click="checkImport"><Search :size="15"/>检查并预览</button><span v-if="preview" :class="preview.errors?'red-text':'green-text'">{{preview.rows.length}} 行 · {{preview.errors}} 行错误</span><a v-if="importKind==='inventory'" href="/api/export/template" class="text-button">下载模板</a></div><div v-if="preview" class="table-wrap import-preview"><table><thead><tr><th>行</th><th>器件</th><th>类别 / 封装</th><th>检查结果</th></tr></thead><tbody><tr v-for="r in preview.rows.slice(0,50)" :key="r.row_no"><td>{{r.row_no}}</td><td>{{r.name}}<small v-if="r.supplier_code">{{r.supplier_code}}</small></td><td>{{r.category||'待核对'}} / {{r.package}}</td><td :class="r.errors.length?'red-text':'green-text'">{{r.errors.join('；')||(r.reuse_id?'复用已有档案':'通过')}}<small v-for="warning in r.warnings" :key="warning" class="warm-text">{{warning}}</small></td></tr></tbody></table><p v-if="preview.rows.length>50" class="form-hint">仅展示前 50 行；提交时处理全部 {{preview.rows.length}} 行。</p></div><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy||!preview||preview.errors>0">{{importKind==='bom'?'创建项目并核料':'确认导入'}}</button></div></form>
   <form v-else-if="modal==='match'&&matchLine" @submit.prevent="saveMatch"><div class="callout warm"><strong>需求：{{matchLine.name}} / {{matchLine.package||'未提供封装'}}</strong><p v-if="matchLine.supplier_code">商城编号 {{matchLine.supplier_code}}</p><p v-if="matchLine.value">数值 {{matchLine.value}}</p><p v-for="warning in matchLine.warnings" :key="warning">{{warning}}</p><p v-if="Object.keys(matchLine.specs_data).length">{{Object.entries(matchLine.specs_data).map(([k,v])=>k+' '+v).join(' · ')}}</p><p v-if="matchLine.missing_specs?.length">BOM 未指定{{matchLine.missing_specs.join('、')}}，请按实际用途核对库存参数。</p><p v-if="matchLine.unmatched_reason">{{matchLine.unmatched_reason}}</p><template v-if="matchLine.part?.id===matchForm.part_id"><p v-if="matchLine.match==='supplier_code'">已按商城编号 {{matchLine.part?.supplier_code}} 自动关联；以下资料差异供核对。</p><p v-if="matchLine.match==='model'">已按完整型号自动关联。</p><p v-for="note in matchLine.match_notes" :key="note">{{note}}</p></template><p v-if="matchLine.match==='value_package'">已按类别、数值和封装自动关联唯一候选。</p></div><label>关联已有器件<select v-model="matchForm.part_id" required><option value="" disabled>请选择器件</option><option v-for="p in activeParts" :key="p.id" :value="p.id">{{partLabel(p)}} · {{p.package}}<template v-if="specLabel(p)"> · {{specLabel(p)}}</template></option></select></label><div v-if="matchPart" class="callout"><strong>库存：{{partLabel(matchPart)}} / {{matchPart.package}}</strong><p>{{specLabel(matchPart)||'无附加参数'}}</p><p v-if="matchPart.supplier_code">商城编号 {{matchPart.supplier_code}}</p><p>精确可用 {{matchPart.available}} 颗</p></div><label>确认依据<textarea v-model="matchForm.reason" required rows="2" placeholder="例如：已核对数据手册，封装尺寸与引脚一致，参数满足本项目需求。"></textarea></label><label class="checkbox-label"><input v-model="matchForm.confirmed" type="checkbox" required>我已核对参数、封装与引脚，确认仅用于此项目。</label><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy||!matchForm.confirmed">保存项目匹配</button></div></form>
   <form v-else-if="modal==='purchase'" @submit.prevent="savePurchase"><div class="form-grid"><label class="span2">采购器件<select v-model="purchaseForm.part_id" required><option value="" disabled>请选择已建档器件</option><option v-for="p in activeParts" :key="p.id" :value="p.id">{{productName(p)}} · {{p.package}} · {{p.name}}</option></select><span class="row"><span v-if="!activeParts.length" class="subtle">还没有器件档案。</span><button type="button" class="text-button" @click="createPurchasePart">＋ 新建器件档案</button></span></label><label>采购数量<input v-model.number="purchaseForm.quantity" type="number" min="1" step="1" required></label><label>关联项目<select v-model="purchaseForm.project_id"><option value="">日常补货</option><option v-for="p in data.projects" :value="p.id" :key="p.id">{{p.name}}</option></select></label><label class="span2">供应商<input v-model="purchaseForm.supplier" placeholder="立创 / 淘宝 / 其他"></label><label class="span2">备注<textarea v-model="purchaseForm.notes" rows="2" placeholder="采购链接、订单号等"></textarea></label></div><div v-if="data.purchases.some(p=>p.part_id===purchaseForm.part_id&&!['received','cancelled'].includes(p.status))" class="callout warm">此器件已有未完成采购，请核对是否需要重复购买。</div><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">添加到采购清单</button></div></form>
   <form v-else-if="modal==='receive'&&receivePurchase" @submit.prevent="receive"><div class="callout"><strong>{{cleanProductName(receivePurchase.product_name||receivePurchase.part_name)}} / {{receivePurchase.package}}</strong><p>型号 {{receivePurchase.part_name}}</p><p>待验收 {{receivePurchase.quantity-receivePurchase.received}} 颗，允许分批到货。</p></div><div class="form-grid"><label class="span2">放入格子<select v-model="receiveForm.slot_id" required><option value="" disabled>请选择空格或同器件位置</option><option v-for="s in slotOptions" :key="s.id" :value="s.id">{{s.label}}</option></select></label><label>本次实际验收数量<input v-model.number="receiveForm.quantity" type="number" min="1" :max="receivePurchase.quantity-receivePurchase.received" step="1" required></label></div><p class="form-hint">请核对实物与型号。放入估算库存时会保留估算状态；建议选择空格或精确库存位置。</p><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy">确认验收并入库</button></div></form>
   <form v-else-if="modal==='restore'&&restoreCounts" @submit.prevent="restore"><div class="callout warm">恢复会用备份替换当前业务数据与附件；当前成员和登录保留。原数据先保存为恢复前快照。</div><p>{{restoreFile?.name}}</p><dl class="restore-summary"><template v-for="(v,k) in restoreCounts" :key="k"><dt>{{({parts:'器件',boxes:'收纳盒',stock:'存放记录',projects:'项目',purchases:'采购',movements:'流水'} as Record<string,string>)[k]}}</dt><dd>{{v}}</dd></template></dl><label class="checkbox-label"><input v-model="restoreConfirmed" type="checkbox" required>已检查备份内容，确认替换当前数据。</label><div class="modal-footer"><button type="button" class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy||!restoreConfirmed">恢复此备份</button></div></form>
   <form v-else-if="modal==='project-delete'&&project" @submit.prevent="deleteProject"><p>确定删除项目「<strong>{{project.name}}</strong>」？</p><p class="form-hint">将删除 {{project.lines.length}} 项 BOM 及匹配记录。器件档案、实物库存和历史流水保留。</p><p v-if="project.status==='reserved'" class="callout warm">该项目占用的库存会释放，其他项目可以重新使用。</p><p v-if="project.status==='built'" class="callout warm">已经领料的数量不会退回库存。</p><p v-if="projectPurchaseCount" class="form-hint">关联的 {{projectPurchaseCount}} 条采购记录会保留为独立采购，并注明原项目。</p><div class="callout">删除前会自动保存完整备份，需要找回时可在「数据与备份」恢复删除前的快照。</div><div class="modal-footer"><button type="button" class="secondary" :disabled="busy" @click="modal=''">取消</button><button class="primary danger" :disabled="busy">确认删除项目</button></div></form>
   <div v-else-if="modal==='issue'&&project"><div class="callout">为「{{project.name}}」{{project.boards}} 块板统一领料。确认后会从精确库存扣减全部已占用数量，并写入流水。</div><p class="form-hint">请按核料结果中的位置取料。完成后项目标记为已领料，不可重复执行。</p><div class="modal-footer"><button class="secondary" @click="modal=''">取消</button><button class="primary" :disabled="busy" @click="run(async()=>{await api(`/projects/${project!.id}/issue`,'POST');await refresh();modal='';notify('整单领料完成');})">确认已取料并扣减库存</button></div></div>
  </section></div>
  <div v-if="printReady" class="print-area"><h1>料格 · 收纳标签</h1><section v-for="b in visibleBoxes" :key="b.id"><h2>{{b.code}} · {{b.name}} · {{b.area}}</h2><div class="print-labels"><div v-for="s in b.slots" :key="s.id"><img :src="'/api/qr/slot/'+s.id" :alt="b.code+'/'+cell(s)+' 标签码'"><strong>{{b.code}} / {{cell(s)}}</strong><span>{{partAt(s)?.name||'空格'}}</span><small>{{partAt(s)?.package}} {{partAt(s)?specLabel(partAt(s)!):''}}</small></div></div></section></div>
 </div>
</template>
